Translate("esES", "city-of-dalaran", {
	title = "Ciudad de Dalaran",
	aliases = { "Dalaran", "la ciudad de los magos" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Ciudad de Dalaran vuelve a alzarse en la orilla occidental del {red:lordamere-lake}Lago Lordamere{/red}, al pie de las {link:alterac-mountains}Montañas de Alterac{/link}. Sus agujas violetas se elevan sobre murallas nuevas y calles luminosas, sus bancos y posadas están abiertos, y sus magos caminan de nuevo entre mercaderes, artesanos y huéspedes de tierras lejanas. Durante años la ciudad se ocultó tras una gran cúpula de luz mientras sus magos la reconstruían. Esa barrera ha caído. El mundo puede ver de nuevo Dalaran, y Dalaran debe ahora rendir cuentas ante el mundo.]=],
		},
		{
			title = "Orígenes",
			text = [=[La historia de {link:city-of-dalaran}Dalaran{/link}, la primera de las ciudades libres de {link:arathor}Arathor{/link} y hogar del {link:kirin-tor}Kirin Tor{/link}, se cuenta en su propia crónica. En la {link:third-war}Tercera Guerra{/link}, la {link:scourge}Plaga{/link} llegó a sus puertas y se llevó el libro de hechizos de {link:medivh}Medivh{/link}, y {link:archimonde}Archimonde{/link} destruyó la ciudad con un solo hechizo. Los magos supervivientes volvieron a las ruinas. Alzaron una vasta cúpula mágica sobre el corazón de su ciudad, y tras ella se pusieron a trabajar. Fuera, las patrullas de {link:the-wizards-of-ambermill}magos de Dalaran{/link} y sus elementales atados guardaban las afueras en ruinas, y pocos de los que se acercaban eran bienvenidos.]=],
		},
		{
			title = "El presente",
			text = [=[La obra está terminada, o casi. Nadie fuera del {link:kirin-tor}Kirin Tor{/link} sabe aún decir por qué cayó la barrera. La ciudad está abierta, pero no está en paz. Los encantamientos se desvían, los constructos arcanos se liberan de sus ataduras y se ha sentido energía demoníaca en sus calles. Los investigadores del Kirin Tor hablan en voz baja de una perturbación que empeora día a día, y se les ha ordenado mantener la calma entre los ciudadanos. El Kirin Tor se cuenta ahora entre las naciones de la {link:alliance}Alianza{/link}. La {link:horde}Horda{/link} no es bienvenida aquí, y los guardias de la ciudad tratan a los suyos como enemigos. En su lugar han llegado nuevos amigos: la {link:high-order}High Order{/link} de los {link:skyborne}Skyborne{/link}, cuyas naves skycutter navegan entre Dalaran y {link:zephras-isle}Zephras Isle{/link} a través de los planos.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}El {link:kirin-tor}Kirin Tor{/link}.{/b} Archimagos, archiveros, arcanistas e investigadores, los amos de la ciudad.
• {b}Los guardias de Dalaran.{/b} Guardias y ejecutores del Kirin Tor, y centinelas arcanos que vigilan por su cuenta.
• {b}Ciudadanos y comerciantes.{/b} Banqueros, posaderos, herreros, sastres, joyeros y un juguetero, y un orfanato con su matrona.
• {b}Los {link:skyborne}Skyborne{/link}.{/b} Magos de la {link:high-order}High Order{/link}, que llegan al muelle de los skycutter de la ciudad.
• {b}Visitantes.{/b} Entre ellos, un maestro de druidas y un Altonato que ha venido de lejos.]=],
		},
		{
			title = "Historia",
			text = [=[• {b}La fundación.{/b} Dalaran fue la primera ciudad de {link:arathor}Arathor{/link} en gobernarse a sí misma, y sus magos fundaron el {link:kirin-tor}Kirin Tor{/link}.
• {b}La caída.{/b} En la {link:third-war}Tercera Guerra{/link} la ciudad fue destruida.
• {b}La barrera.{/b} Los magos reconstruyeron Dalaran tras una cúpula que mantenía fuera al mundo.
• {b}El presente.{/b} La barrera ha desaparecido, y la ciudad ha abierto sus puertas a sus aliados.]=],
		},
		{
			title = "Saber de la ciudad",
			text = [=[• Los {link:the-wizards-of-ambermill}magos de Dalaran{/link} vigilan ahora los caminos del norte. En el {link:silverpine-forest}Bosque de Argénteos{/link} dicen que lo hacen desde que cayó la barrera.
• El archimago {link:archmage-ansirem-runeweaver}Ansirem Runeweaver{/link} escribió una vez un tomo sobre las leyendas de los trols Gurubashi. Su hija, para su pesar, se hizo pirata.
• El {link:kirin-tor}Kirin Tor{/link} mantiene un portal para la {link:high-order}High Order{/link}, para que sus jóvenes magos puedan llegar a {link:stormwind-city}Ventormenta{/link} y conocer allí al regente.]=],
		},
	},
})

Translate("esES", "the-eventide", {
	title = "The Eventide",
	aliases = { "Eventide" },
	sections = {
		{
			title = "Resumen",
			text = [=[The Eventide es uno de los barrios de la ciudad reconstruida de {link:city-of-dalaran}Dalaran{/link}. Como el resto de la ciudad, se alzó de nuevo tras la gran barrera mientras el mundo exterior no podía verlo, y solo hace poco se ha abierto a los visitantes. Sus calles son nuevas, y también lo son muchas de las personas que las recorren. Ninguna crónica registra aún quién habita en The Eventide, ni qué construyeron allí primero los magos. Quienes recorren sus calles encuentran una ciudad orgullosa de su restauración, y más inquieta de lo que quiere admitir.]=],
		},
	},
})

Translate("esES", "archmage-ansirem-runeweaver", {
	title = "Archimago Ansirem Runeweaver",
	subtitle = "Archimago del Kirin Tor",
	found = "La Ciudad de Dalaran",
	hint = [=[Busque al archimago del Kirin Tor cuyo saber llega desde Tuercespina hasta los cielos.]=],
	allegiance = "Kirin Tor",
	aliases = { "Ansirem Runeweaver", "Ansirem" },
	sections = {
		{
			title = "Resumen",
			text = [=[El archimago Ansirem Runeweaver es uno de los grandes magos del {link:kirin-tor}Kirin Tor{/link}. Ha trabajado durante la larga reconstrucción de {link:city-of-dalaran}Dalaran{/link}, y su saber es inmenso. Hace años escribió un tomo sobre las leyendas del Imperio Gurubashi, y sabe más de las reliquias trol de {link:stranglethorn-vale}Tuercespina{/link} que cualquier erudito del norte. También es padre, y su única hija le ha roto el corazón de la manera más insólita: se fue a {link:booty-bay}Bahía del Botín{/link} para hacerse pirata.]=],
		},
		{
			title = "Importancia",
			text = [=[Ansirem es el rostro del {link:kirin-tor}Kirin Tor{/link} ante el mundo que hay más allá de sus muros. Responde a las preguntas de príncipes y piratas por igual. Cuando los {link:skyborne}Skyborne{/link} de {link:zephras-isle}Zephras Isle{/link} se vieron amenazados por el culto del {link:al-akir}Señor del Viento{/link}, fue Ansirem quien acudió con los magos del Kirin Tor para ponerse a su lado. Su amistad es ahora la alianza de su orden.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Estudia la maldición de la Piedra de las Mareas para los goblins de {link:booty-bay}Bahía del Botín{/link}.
• Encontró una daga trol en {link:stranglethorn-vale}Tuercespina{/link} y se la dio a su obstinada hija, {link:catelyn-the-blade}Catelyn{/link}.
• Acudió a {link:zephras-isle}Zephras Isle{/link} con el {link:kirin-tor}Kirin Tor{/link} y conoció al Magíster Supremo de la {link:high-order}High Order{/link}.
• Envía a los jóvenes druidas de los {link:skyborne}Skyborne{/link} al {link:cenarion-circle}Círculo Cenarion{/link}, para que aprendan a salvar su hogar.]=],
		},
	},
	chapters = {
		{
			title = "La Piedra de las Mareas",
			hint = "Lleve al archimago un enigma mágico de Tuercespina.",
			text = [=[Los brazales procedían de elementales de agua del lejano sur, y llevaban el residuo de una maldición trol. Ansirem estaba encantado. Había escrito sobre la Piedra de las Mareas hacía mucho. El mago que tenía la Piedra, descubrió, amplificaba su poder mediante un altar. Se le podía superar con la reliquia adecuada, y él sabía exactamente cuál: una antigua daga trol. Solo había un problema. Se la había dado a su hija.]=],
		},
		{
			title = "Los hijos de la naturaleza",
			hint = "Hable con el archimago siendo un joven druida de los cielos.",
			text = [=[A los jóvenes druidas de los {link:skyborne}Skyborne{/link}, Ansirem les ofrece un consejo que no esperaban de un mago. Existe en {link:azeroth}Azeroth{/link} una antigua orden de naturalistas, les dice, y una elfa de la noche de {link:stormwind-city}Ventormenta{/link} puede mostrarles el camino a su bastión en el {link:moonglade}Claro de la Luna{/link}. Si quieren salvar su hogar, tienen mucho que aprender.]=],
		},
	},
	mentions = {
		{ text = "Análisis mágico" },
		{ text = "La llave de Ansirem" },
		{ text = "Hijo de la naturaleza" },
		{
			text = [=[Enfrentarse a {link:high-priestess-lorthuna}Lorthuna{/link}, en las agujas de {link:zephras-isle}Zephras{/link}]=],
		},
	},
	bonds = {
		{ id = "elaadrin-evengale", name = "Elaadrin Evengale", note = "lo conoció en las agujas" },
		{ id = "archmage-modera", name = "Archimaga Modera", note = "una archimaga compañera" },
		{ id = "denaaris-stargale", name = "Denaaris Stargale", note = "recibe a la High Order en su ciudad" },
	},
})

Translate("esES", "archmage-modera", {
	title = "Archimaga Modera",
	subtitle = "Archimaga del Kirin Tor",
	found = "La Ciudad de Dalaran",
	hint = [=[Busque a la anciana archimaga que sirve al Kirin Tor desde la Segunda Guerra.]=],
	allegiance = "Kirin Tor",
	aliases = { "Modera" },
	sections = {
		{
			title = "Resumen",
			text = [=[La archimaga Modera es uno de los miembros más antiguos del consejo que gobierna el {link:kirin-tor}Kirin Tor{/link}. Formaba parte de los magos que gobernaban {link:city-of-dalaran}Dalaran{/link} en los días de la {link:second-war}Segunda Guerra{/link}. Antes de la peste, habló contra {link:kel-thuzad}Kel'Thuzad{/link} cuando salió a la luz su estudio de la nigromancia, y advirtió que sus métodos los condenarían a todos. Su advertencia fue escuchada, y él fue expulsado. Sobrevivió a la caída de la ciudad y se quedó para verla alzarse de nuevo.]=],
		},
		{
			title = "Importancia",
			text = [=[Modera es una memoria viva del antiguo {link:kirin-tor}Kirin Tor{/link}, y una voz que acertó sobre el hombre que destruyó {link:lordaeron}Lordaeron{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Aún no se ha recogido nada sobre su papel en la reconstrucción, ni sobre lo que piensa de la caída de la barrera.]=],
		},
	},
	bonds = {
		{ id = "archmage-ansirem-runeweaver", name = "Archimago Ansirem Runeweaver", note = "un archimago compañero" },
		{ id = "kel-thuzad", name = "Kel'Thuzad", note = "habló contra él" },
	},
})

