Translate("esES", "investigator-silva", {
	title = "Investigadora Silva",
	subtitle = "Investigadora del Kirin Tor",
	found = [=[Un rincón tranquilo de Dalaran, con la investigadora Kath'leen]=],
	hint = [=[Preste oído a las dos investigadoras que hablan en voz baja en las calles de Dalaran.]=],
	allegiance = "Kirin Tor",
	aliases = { "Silva" },
	sections = {
		{
			title = "Resumen",
			text = [=[La investigadora Silva trabaja junto a la investigadora {link:investigator-kath-leen}Kath'leen{/link} en un asunto que inquieta al {link:kirin-tor}Kirin Tor{/link}. Las dos han estudiado los hallazgos obtenidos de un pilón, y Silva quiere repasarlos otra vez, por si se les escapó algo. Silva se atiene a las órdenes recibidas. Hasta que lo sepan con certeza, el silencio es la mejor manera de mantener la calma en la ciudad.]=],
